<script setup>
import { computed, onMounted, ref } from 'vue'
import { useOrganizationStore } from '@/stores/organization'
import { createAcquisitionDiagnosis, createAcquisitionProject, createActionPlan, createAcquisitionSnapshot, listAcquisitionDiagnoses, listAcquisitionProjects, listActionPlans, listAcquisitionSnapshots, createWeeklyGrowthReview } from '@/api/growth'
import { AI_SERVICE_BOUNDARY, operationError, operationStatus } from '@/constants/operationsLanguage'
const organization = useOrganizationStore(), projects = ref([]), current = ref(null), history = ref({ diagnoses: [], plans: [], snapshots: [] })
const loading = ref(true), detailLoading = ref(false), error = ref(''), busy = ref(false), message = ref('')
const problemOptions = [{ code: 'leads_low', label: '有播放，没咨询' }, { code: 'arrival_low', label: '有咨询/预约，没到店' }, { code: 'sale_low', label: '到店了，没成交' }, { code: 'renewal_low', label: '成交了，续费差' }, { code: 'unknown', label: '不知道问题在哪里' }]
const form = ref({ problem_code: 'unknown', course_name: '', age_range: '', city: '', views: '', valid_leads: '', appointments: '', arrivals: '', trial_completed: '', new_sales: '', renewals: '', eligible_renewals: '', spend: '', content_note: '', sales_note: '', delivery_note: '' })
const config = () => ({ headers: organization.headers() })
const screenshotDiagnoses = computed(() => history.value.diagnoses.filter(i => i.source_type === 'private_asset' || i.input_data?.source === 'private_image'))
const latestDiagnosis = computed(() => history.value.diagnoses[0]?.output_data || {})
const nextSuggestion = computed(() => history.value.snapshots[0]?.summary || history.value.plans[0]?.plan_data?.nextStageSuggestion || latestDiagnosis.value.actions?.[0]?.title || '')
function normalize(items) { return (items || []).map(i => ({ ...i, input_data: parse(i.input_data), output_data: parse(i.output_data), plan_data: parse(i.plan_data), metrics: parse(i.metrics) })) }
function parse(value) { if (!value || typeof value === 'object') return value || {}; try { return JSON.parse(value) } catch { return {} } }
function userError(error, action) { return operationError(error, { action }).message }
function formMetrics() { return Object.fromEntries(Object.entries(form.value).filter(([key, value]) => ['views','valid_leads','appointments','arrivals','trial_completed','new_sales','renewals','eligible_renewals','spend'].includes(key) && value !== '').map(([key, value]) => [key, Number(value)])) }
async function loadProjects() { loading.value = true; error.value = ''; try { await organization.load(); const r = await listAcquisitionProjects(config()); projects.value = r.projects || []; await selectProject(projects.value[0] || null) } catch (e) { error.value = userError(e, '打开以前的招生记录') } finally { loading.value = false } }
async function selectProject(project) { current.value = project; history.value = { diagnoses: [], plans: [], snapshots: [] }; if (!project) return; detailLoading.value = true; error.value = ''; try { const [d,p,s] = await Promise.all([listAcquisitionDiagnoses(project.id, config()), listActionPlans(project.id, config()), listAcquisitionSnapshots(project.id, config())]); history.value = { diagnoses: normalize(d.diagnoses), plans: normalize(p.plans), snapshots: normalize(s.snapshots) } } catch(e) { error.value = userError(e, '打开这次经营复盘') } finally { detailLoading.value = false } }
async function startProject() { busy.value = true; message.value = ''; try { const name = form.value.course_name ? `${form.value.course_name}招生行动` : '本周招生行动'; const r = await createAcquisitionProject({ name, goal: '提高有效咨询、到店和正价报名', channels:['douyin','xiaohongshu'] }, config()); projects.value.unshift(r.project); await selectProject(r.project); message.value='本周行动已建立，请填写招生数据' } catch(e) { error.value=userError(e, '建立本周招生行动') } finally { busy.value=false } }
async function diagnose() { if (!current.value) await startProject(); if (!current.value) return; busy.value=true; try { const inputData = { businessLoop: { ...form.value, ...formMetrics() } }; await createAcquisitionDiagnosis(current.value.id,{ channelCode:'douyin', diagnosisType:'funnel', inputData },config()); message.value='本周问题已整理，数据不足的判断需要顾问确认'; await selectProject(current.value) } catch(e){ error.value=userError(e, '整理本周招生问题') } finally{ busy.value=false } }
async function savePlan() { if (!current.value || !history.value.diagnoses[0]) return; busy.value=true; try { await createActionPlan(current.value.id, { diagnosisId: history.value.diagnoses[0].id, title: '7天咨询到报名行动' }, config()); message.value='7天行动已保存'; await selectProject(current.value) } catch(e) { error.value=userError(e, '保存7天行动') } finally { busy.value=false } }
async function saveSnapshot() { if (!current.value) return; busy.value=true; try { await createAcquisitionSnapshot(current.value.id, { metrics: formMetrics(), summary: '本周期经营数据已提交' }, config()); message.value='本周期经营结果已保存'; await selectProject(current.value) } catch(e) { error.value=userError(e, '保存本周期经营数据') } finally { busy.value=false } }
async function weeklyReview() { if (!current.value) return; busy.value=true; try { const r=await createWeeklyGrowthReview(current.value.id,{snapshot:history.value.snapshots[0]||{metrics:formMetrics()}, triggerConsultant:true},config()); message.value=`7天结果：${r.review.primaryIssue}` } catch(e){ error.value=userError(e, '回看这7天的结果') } finally{ busy.value=false } }
onMounted(loadProjects)
</script>
<template><main class="page"><header><div><span class="eyebrow">本周招生行动</span><h1>看看家长在哪一步没有继续</h1><p>按咨询、预约体验、到店、完成体验和正价报名填写聚合数据，先确定一个主要问题。</p></div><button class="primary" @click="startProject" :disabled="busy">＋ 开始本周记录</button></header>
<section v-if="loading" class="state" aria-live="polite">正在打开以前的招生行动记录…</section><section v-else-if="error && !current" class="state error"><b>暂时没能打开记录</b><span>{{ error }}</span><button @click="loadProjects">再试一次</button></section>
<div v-else class="workspace"><aside aria-label="招生行动记录"><h2>以前的记录</h2><div v-if="!projects.length" class="empty">还没有招生行动记录，从本周第一次填写开始。</div><button v-for="p in projects" :key="p.id" class="project" :class="{active:current?.id===p.id}" @click="selectProject(p)"><b>{{p.name}}</b><small>{{p.goal||'提高家长咨询、到店和报名'}}</small></button></aside>
<section class="content"><div v-if="error" class="inline-error" role="alert">{{error}}<button @click="selectProject(current)">重试</button></div><article class="hero"><div><span class="tag">{{current?'本周正在推进':'7天招生行动'}}</span><h2>{{current?.name||'先确定本周最想解决的问题'}}</h2><p>{{current?.goal||'只填聚合数据，不需要录入儿童姓名或联系方式。'}}</p></div><button class="gold" @click="diagnose" :disabled="busy">看看问题出在哪</button></article>
<article class="input-card"><h3>本周最想解决什么？</h3><div class="problem-options"><label v-for="option in problemOptions" :key="option.code" :class="{selected:form.problem_code===option.code}"><input v-model="form.problem_code" type="radio" name="problem" :value="option.code">{{option.label}}</label></div><div class="form-grid"><label>课程名称<input v-model="form.course_name" placeholder="如：少儿篮球体验课"></label><label>适龄范围<input v-model="form.age_range" placeholder="如：6-12岁"></label><label>城市<input v-model="form.city" placeholder="如：贵阳"></label><label>内容播放量<input v-model="form.views" inputmode="numeric" type="number" min="0"></label><label>有效咨询<input v-model="form.valid_leads" inputmode="numeric" type="number" min="0"></label><label>预约体验人数<input v-model="form.appointments" inputmode="numeric" type="number" min="0"></label><label>实际到店人数<input v-model="form.arrivals" inputmode="numeric" type="number" min="0"></label><label>完成体验课人数<input v-model="form.trial_completed" inputmode="numeric" type="number" min="0"></label><label>正价报名人数<input v-model="form.new_sales" inputmode="numeric" type="number" min="0"></label><label>续费人数<input v-model="form.renewals" inputmode="numeric" type="number" min="0"></label><label>应续费人数<input v-model="form.eligible_renewals" inputmode="numeric" type="number" min="0"></label><label>本期招生投入<input v-model="form.spend" inputmode="numeric" type="number" min="0"></label></div><p class="hint">不填写的指标不会被系统猜测；这项暂时没有数据也可以继续，但判断结果会标记为需要顾问确认。</p><div class="form-actions"><button class="primary" @click="diagnose" :disabled="busy">整理主要问题</button><button @click="saveSnapshot" :disabled="busy || !current">保存本周期结果</button></div></article>
<div v-if="detailLoading" class="state">正在整理以前的问题、行动和经营结果…</div><template v-else-if="current"><div class="review-grid"><article class="card"><h3>主要问题与本周行动</h3><button @click="weeklyReview" :disabled="busy">回看这7天的结果</button><button v-if="history.diagnoses.length" @click="savePlan" :disabled="busy">制定7天行动</button><div v-if="!history.diagnoses.length" class="empty">还没有问题判断，先填写本周招生数据。</div><div v-for="d in history.diagnoses" :key="d.id" class="item"><b>{{d.channel_code||'综合招生'}} · {{operationStatus(d.output_data?.needs_review ? 'needs_review' : d.status).label}}</b><p><b>当前最需要解决的问题：</b>{{d.output_data?.phenomenon||d.output_data?.aiJudgment?.conclusion||d.output_data?.conclusion||'结果正在复核'}}</p><small>判断依据：{{(d.output_data?.evidence||d.output_data?.basis||[]).join?.('；')||'聚合指标待核验'}} · 可能原因：{{d.output_data?.primaryCause||'待确认'}} · 参考来源：{{d.output_data?.basisType||'已记录的经营数据'}} · 最近核对：{{d.output_data?.lastVerified||'—'}} · {{d.output_data?.needs_review?'需要顾问确认':'已结合现有记录确认'}}</small><p>本周先做：{{(d.output_data?.actionCards||d.output_data?.actions||[]).slice?.(0,2).map?.(a=>a.title||a).join?.('；')||'—'}}<br>观察指标：{{(d.output_data?.validationMetrics||[]).join?.('；')||'—'}}<br>停止或求助条件：{{(d.output_data?.stopConditions||[]).join?.('；')||'—'}}</p></div></article><article class="card"><h3>7天行动安排</h3><div v-if="!history.plans.length" class="empty">还没有行动安排，确认主要问题后再制定。</div><div v-for="p in history.plans" :key="p.id" class="item"><b>{{p.title}}</b><p>{{p.plan_data?.strategy||p.plan_data?.summary||'方案已保存，可继续执行。'}}</p></div></article><article class="card"><h3>招生页面截图参考</h3><div v-if="!screenshotDiagnoses.length" class="empty">还没有截图记录；上传后会整理可读内容，并标出需要顾问确认的地方。</div><div v-for="d in screenshotDiagnoses" :key="d.id" class="item"><b>截图 #{{d.source_id}}</b><p>{{d.output_data?.aiJudgment?.conclusion||'正在整理，完成后请顾问确认'}}</p><small>{{d.output_data?.humanConfirmationItems?.join('；')}}</small></div></article><article class="card"><h3>以前的经营结果</h3><div v-if="!history.snapshots.length" class="empty">还没有保存经营结果，执行7天后回来登记。</div><div v-for="s in history.snapshots" :key="s.id" class="item"><b>{{s.snapshot_date||'本周期记录'}}</b><p>{{s.summary||'已保存本周期经营数据'}}</p><small>{{Object.entries(s.metrics||{}).map(([k,v])=>`${k}：${v}`).join(' · ')}}</small></div></article></div><article class="next"><span>接下来先做</span><h3>{{nextSuggestion||'先填写本周招生数据，执行后保存本周期结果。'}}</h3><p>{{ AI_SERVICE_BOUNDARY.basedOnInput }}{{ AI_SERVICE_BOUNDARY.referenceOnly }}{{ AI_SERVICE_BOUNDARY.compareAfterExecution }}</p></article></template></section></div><p v-if="message" class="message">{{message}}</p></main></template>
<style scoped>.page{min-height:100vh;padding:36px clamp(16px,4vw,56px);background:#f5f3ec;color:#17231c}.page>header{max-width:1320px;margin:auto;display:flex;justify-content:space-between;gap:20px}.eyebrow{color:#8b681e;font-size:11px;font-weight:800}.page h1{margin:8px 0}.page p{color:#66736b;line-height:1.6}.primary,.gold,.state button,.inline-error button{min-height:44px;padding:0 16px;border-radius:9px;background:#1e563a;color:#fff;font-weight:700}.workspace{max-width:1320px;margin:24px auto;display:grid;grid-template-columns:230px 1fr;gap:18px}aside,.card{background:#fff;border:1px solid #dce2dc;border-radius:14px;padding:18px}aside h2{font-size:16px;margin-bottom:12px}.project{width:100%;min-height:56px;text-align:left;padding:10px;border-radius:9px}.project b,.project small{display:block}.project small{color:#738077;margin-top:4px}.project.active{background:#e6f0e8;color:#174c30}.hero{background:#173d2c;color:#fff;border-radius:16px;padding:24px;display:flex;justify-content:space-between;align-items:center}.hero h2{color:#fff;margin:10px 0}.gold{background:#dcae53;color:#302207}.tag{background:#efe8d5;color:#745719;border-radius:99px;padding:5px 9px;font-size:11px}.review-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.item{padding:13px 0;border-bottom:1px solid #e6e9e5}.item:last-child{border:0}.item p{margin-top:5px}.item small{color:#7a827e}.empty,.state{color:#77817b;padding:24px 4px}.state{max-width:1320px;margin:24px auto;background:#fff;border-radius:14px}.state span{display:block;margin:8px 0}.error,.inline-error{color:#9b2929}.inline-error{padding:12px;background:#fff1f0;margin-bottom:12px;border-radius:10px}.inline-error button{margin-left:10px}.next{margin-top:14px;background:#efe8d5;border-radius:14px;padding:20px}.next span{color:#80621f;font-size:12px;font-weight:800}.next h3{margin-top:8px}.message{max-width:1320px;margin:auto}@media(max-width:1000px) and (orientation:landscape){.workspace{grid-template-columns:72px 1fr}aside{padding:10px}.project small,aside h2{display:none}.project b{font-size:0}.project b::first-letter{font-size:18px}}@media(max-width:760px),(orientation:portrait) and (max-width:1000px){.page>header,.hero{align-items:stretch;flex-direction:column}.workspace{grid-template-columns:1fr}.review-grid{grid-template-columns:1fr}.primary,.gold{width:100%}}button:focus-visible{outline:3px solid #dcae53;outline-offset:2px}.input-card{margin-top:14px;background:#fff;border:1px solid #dce2dc;border-radius:14px;padding:18px}.problem-options{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 16px}.problem-options label{border:1px solid #dce2dc;border-radius:999px;padding:9px 12px;cursor:pointer}.problem-options label.selected{background:#e6f0e8;border-color:#6c9a78;color:#174c30;font-weight:700}.problem-options input{position:absolute;opacity:0}.form-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.form-grid label{font-size:12px;color:#66736b}.form-grid input{display:block;width:100%;margin-top:5px;min-height:38px;border:1px solid #dce2dc;border-radius:8px;padding:0 9px;box-sizing:border-box}.hint{font-size:12px;margin:14px 0}.form-actions{display:flex;gap:8px}.form-actions button,.card>button{min-height:38px;padding:0 12px;border:1px solid #cbd7cd;border-radius:8px;background:#fff;color:#28543b}.card>button{margin:0 8px 12px 0}.card>button:disabled,.form-actions button:disabled{opacity:.55}@media(max-width:900px){.form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:480px){.form-grid{grid-template-columns:1fr}.problem-options{display:grid}.form-actions{flex-direction:column}.form-actions button{width:100%}}</style>
